import { expect, sample, test, uniqueName } from "../../fixtures";

type ApiClient = Awaited<ReturnType<Parameters<Parameters<typeof test>[2]>[0]["apiAs"]>>;

/** Creates a vendor, uploads all three document kinds, waits for extraction, and submits it. */
async function createVendorInReview(member: ApiClient, label: string): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName(`Review ${label}`),
      category: "services",
      contact_email: `review.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.com`,
    },
  });
  expect(created.status()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const kinds = ["w9", "insurance_certificate", "contract"] as const;
  const documentIds: string[] = [];
  for (const kind of kinds) {
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: {
          name: `${kind}.pdf`,
          mimeType: "application/pdf",
          buffer: Buffer.from("%PDF-1.4 review test document"),
        },
      },
    });
    expect(upload.status()).toBe(201);
    documentIds.push(((await upload.json()) as { id: string }).id);
  }

  // Wait until every document has been extracted before submitting.
  for (const documentId of documentIds) {
    await expect
      .poll(
        async () => {
          const response = await member.get(`/api/documents/${documentId}`);
          return ((await response.json()) as { status: string }).status;
        },
        { timeout: 60_000, intervals: [500, 1000, 2000] },
      )
      .toBe("extracted");
  }

  const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitted.status()).toBe(200);
  expect(((await submitted.json()) as { status: string }).status).toBe("in_review");

  return vendorId;
}

test.describe("review vendors", () => {
  test(
    "the review queue shows lowest confidence first",
    { tag: "@REV-03" },
    async ({ apiAs }) => {
      // Arrange: two vendors in review, signed in as a reviewer.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const [firstVendorId, secondVendorId] = await Promise.all([
        createVendorInReview(member, "Alpha"),
        createVendorInReview(member, "Beta"),
      ]);

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const items = (await response.json()) as Array<{
        vendor_id: string;
        lowest_confidence: number;
      }>;
      expect(items.length).toBeGreaterThanOrEqual(2);

      // The queue is ordered by lowest field confidence, ascending.
      for (let i = 1; i < items.length; i++) {
        expect(items[i].lowest_confidence).toBeGreaterThanOrEqual(items[i - 1].lowest_confidence);
      }
      expect(items[0].lowest_confidence).toBe(
        Math.min(...items.map((item) => item.lowest_confidence)),
      );

      // Both vendors under test appear, and the one with lower confidence comes first.
      const ids = items.map((item) => item.vendor_id);
      const firstIndex = ids.indexOf(firstVendorId);
      const secondIndex = ids.indexOf(secondVendorId);
      expect(firstIndex).toBeGreaterThanOrEqual(0);
      expect(secondIndex).toBeGreaterThanOrEqual(0);
      const firstItem = items[firstIndex];
      const secondItem = items[secondIndex];
      if (firstItem.lowest_confidence < secondItem.lowest_confidence) {
        expect(firstIndex).toBeLessThan(secondIndex);
      } else if (secondItem.lowest_confidence < firstItem.lowest_confidence) {
        expect(secondIndex).toBeLessThan(firstIndex);
      }
    },
  );
});
